mapper.select:
SELECT tracking_process_id, request_tracking_id, tracking_process_identifier, trckPrcIdtifier, tracking_process_type, federated_twin_id, federated_digital_object_id, digital_twin_id, digital_object_id, tracking_command, tracking_kafka_group, tracking_kafka_topic, tracking_value_info, data_filter_type, buffer_size, event_occurred_count, event_condition, event_delay, event_end_date, context_url, entity_id, ngsi_type, timeproperty, last_observed_at, data_link_type, tracking_status, create_time, tracking_status_change_time FROM tracking_process_info tp WHERE 1=1
AND tracking_process_id = #{trackingProcessId}
AND request_tracking_id = #{requestTrackingId}
AND tracking_process_identifier = #{trckPrcIdtifier}
AND tracking_status = #{trackingStatus}
AND tracking_status in
#{item}
AND exists ( select 1 from tracking_topic_info tt where tp.request_tracking_id = tt.request_tracking_id and tp.tracking_process_id = tt.tracking_process_id and tp.tracking_kafka_topic = tt.topic_name )
ORDER BY tracking_process_id
LIMIT #{start},#{end}

SELECT tracking_process_id, request_tracking_id, tracking_process_identifier, trckPrcIdtifier, tracking_process_type, federated_twin_id, federated_digital_object_id, digital_twin_id, digital_object_id, tracking_command, tracking_kafka_group, tracking_kafka_topic, tracking_value_info, data_filter_type, buffer_size, event_occurred_count, event_condition, event_delay, event_end_date, context_url, entity_id, ngsi_type, timeproperty, last_observed_at, data_link_type, tracking_status, create_time, tracking_status_change_time FROM tracking_process_info WHERE 1=1
AND tracking_process_id = #{trackingProcessId}
AND request_tracking_id = #{requestTrackingId}
AND tracking_process_identifier = #{trckPrcIdtifier}
AND tracking_status = #{trackingStatus}
AND tracking_process_identifier = #{trackingProcessIdentifier}

SELECT tracking_process_identifier
  FROM tracking_process_info
 WHERE request_tracking_id = #{requestTrackingId}
   AND trckPrcIdtifier = #{trckPrcIdtifier}
 ORDER BY tracking_process_id
 LIMIT 1

